head.script:
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        edt_TASK_DD.setValue($c.ut.cGetToday("yyyymmdd"));
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40101.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_TASK_DD_onclick
 * @description img_TASK_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_TASK_DD_onclick = function() {
    try {
        popUpCalendar2(edt_TASK_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40101.img_TASK_DD_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40101.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadError
 * @description dts_List_1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40101.dts_List_1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadError
 * @description dts_List_2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40101.dts_List_2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name dts_List_2_OnLoadCompleted
 * @description dts_List_2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40101.dts_List_2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadCompleted
 * @description dts_Item 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    try {
        txb_TRNSM_END_TM.setValue(dts_Item.getCellData(1, "TRNSM_END_TM"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40101.dts_Item_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_1_OnDblClick
 * @description grd_List_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_1_OnDblClick = async function(row, colid) {
    try {
        await scwin.openDetail(row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40101.grd_List_1_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF40101.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List_2, {fileName: "배당금 통보자료 현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40101.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40101.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_List_1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_List_2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_Item",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openDetail
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row, colid) {
    const gViewerStat = "R"; // 처리시 뷰어=P,  조회시 뷰어=R
    const gAcptNo = dts_List_1.getCellData(row, "ACPT_NO");
    if (colid === "FORM_KOR_NM") {
        await $c.stf.openDisclViewer(gAcptNo, gViewerStat);
    }
};
